  expect(service.messages, hasLength(2));

  await service.reconfigure(
    AgentConfig(
      providerKind: 'anthropic',
      modelId: 'claude-test',
      baseUrl: 'https://api.anthropic.com',
      apiKey: '[REDACTED:Sensitive Value]',
